  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["source_code", "string"],
          ["source_language", "string"],
          ["target_language", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are a code analysis expert. Analyze the provided source code and output a JSON object with two keys: 'structure' and 'dependencies'.\n\nFor 'structure': Provide an array of objects. Each object represents a class or function and must have:\n- 'type': either 'class' or 'function'\n- 'name': the name of the class/function\n- 'signature': the full signature (including parameters, return type, access modifiers, etc.) without implementation body.\n\nFor 'dependencies': Provide an array of strings. Include:\n- Built-in libraries/modules required\n- Custom/local imports and dependencies\n- Any external packages referenced\n\nOutput only valid JSON, no additional text.",
        "user": "Source language: {{#1.source_language#}}\n\nCode to analyze:\n{{#1.source_code#}}"
      }
    },
    {
      "id": "3",
      "type": "parameter-extractor",
      "param": {
        "query": ["text", "2"],
        "parameters": [
          ["Array of class/function objects with type, name, and signature", "structure", "array[object]"],
          ["Array of dependency names (built-in and custom)", "dependencies", "array[string]"]
        ],
        "instruction": "Extract the structure and dependencies from the JSON analysis. The JSON has 'structure' and 'dependencies' keys."
      }
    },
    {
      "id": "4",
      "type": "code",
      "param": {
        "variables": [
          ["structure", ["structure", "3"]],
          ["dependencies", ["dependencies", "3"]],
          ["target_lang", ["target_language", "1"]]
        ],
        "outputs": [
          ["formatted_structure", "string"],
          ["formatted_deps", "string"]
        ],
        "code": "def main(structure: list, dependencies: list, target_lang: str):\n\t# Format structure into readable text\n\tstruct_lines = []\n\tfor item in structure:\n\t\tstruct_lines.append(f\"{item['type'].upper()}: {item['name']} - {item['signature']}\")\n\tformatted_structure = '\\n'.join(struct_lines)\n\t\n\t# Format dependencies\n\tformatted_deps = ', '.join(dependencies) if dependencies else 'None identified'\n\t\n\treturn {\n\t\t\"formatted_structure\": formatted_structure,\n\t\t\"formatted_deps\": formatted_deps\n\t}"
      }
    },
    {
      "id": "5",
      "type": "template-transform",
      "param": {
        "variables": [
          ["structure_text", ["formatted_structure", "4"]],
          ["deps_text", ["formatted_deps", "4"]],
          ["target_lang", ["target_language", "1"]]
        ],
        "template": "Translate the following code structure from {{target_lang}}.\n\nCODE STRUCTURE:\n{{structure_text}}\n\nDEPENDENCIES TO CONSIDER:\n{{deps_text}}\n\nInstructions:\n1. Generate ONLY the main structure in {{target_lang}} equivalent\n2. For classes and functions, provide ONLY signatures (no implementations)\n3. Include necessary import/using statements for the dependencies\n4. Preserve the original architecture and naming conventions\n5. Output only code, no explanations"
      }
    },
    {
      "id": "6",
      "type": "llm",
      "param": {
        "system": "You are a expert code translator. Generate only code signatures without implementations.",
        "user": "{{#5.output#}}"
      }
    },
    {
      "id": "7",
      "type": "end",
      "param": {
        "outputs": [["target_code", ["text", "6"]]]
      }
    }
  ],
