def main(github_url: str):
    # Extract owner and repo from GitHub URL
    pattern = r'github\.com/([^/]+)/([^/]+)'
    match = re.search(pattern, github_url)
    if not match:
        return {"file_structure": "Error: Invalid GitHub URL. Please provide a valid GitHub repository URL."}
    owner, repo = match.groups()

    # GitHub API base URL
    api_base = f"https://api.github.com/repos/{owner}/{repo}/contents"

    # Build tree structure
    def build_tree(path=""):
        url = api_base if not path else f"{api_base}/{path}"
        response = requests.get(url)
        if response.status_code != 200:
            return {}

        items = response.json()
        tree = {}

        for item in items:
            name = item["name"]
            if item["type"] == "file":
                tree[name] = "file"
            elif item["type"] == "dir":
                # Recursively get subdirectory contents
                subtree = build_tree(item["path"])
                tree[name] = subtree

        return tree

    # Convert tree to text representation
    def tree_to_text(tree, prefix="", is_last=True):
        lines = []
        items = list(tree.items())

        for i, (name, value) in enumerate(items):
            is_last_item = (i == len(items) - 1)
            connector = "└── " if is_last_item else "├── "

            if value == "file":
                lines.append(f"{prefix}{connector}{name}")
            else:
                # It's a directory
                lines.append(f"{prefix}{connector}{name}/")
                # Prepare prefix for children
                child_prefix = prefix + ("    " if is_last_item else "│   ")
                # Recursively add children
                lines.extend(tree_to_text(value, child_prefix, is_last_item))

        return lines

    # Get the tree structure
    tree = build_tree()

    if not tree:
