    def fetch_readme():
        readme_files = ["README.md", "README", "readme.md", "README.txt"]

        for readme_file in readme_files:
            readme_url = f"{api_base}/contents/{readme_file}"
            response = requests.get(readme_url, headers=headers)

            if response.status_code == 200:
                data = response.json()
                if data.get("content"):
                    # Decode base64 content
                    content = base64.b64decode(data["content"]).decode("utf-8", errors="ignore")
                    return content

        # Try the /readme endpoint
        readme_url = f"{api_base}/readme"
        response = requests.get(readme_url, headers=headers)
        if response.status_code == 200:
            data = response.json()
            if data.get("content"):
                content = base64.b64decode(data["content"]).decode("utf-8", errors="ignore")
                return content

        return "No README file found in the repository."

    # Function to build file structure tree
    def build_tree(path=""):
        url = f"{api_base}/contents/{path}" if path else f"{api_base}/contents"
        response = requests.get(url, headers=headers)

        if response.status_code != 200:
            return {}

        items = response.json()
        tree = {}

        for item in items:
            name = item["name"]
            if item["type"] == "file":
                tree[name] = "file"
            elif item["type"] == "dir":
                subtree = build_tree(item["path"])
                tree[name] = subtree

        return tree

    # Convert tree to text representation
    def tree_to_text(tree, prefix="", is_last=True):
        lines = []
        items = list(tree.items())

        for i, (name, value) in enumerate(items):
            is_last_item = (i == len(items) - 1)
            connector = "└── " if is_last_item else "├── "

            if value == "file":
                lines.append(f"{prefix}{connector}{name}")
            else:
                lines.append(f"{prefix}{connector}{name}/")
                child_prefix = prefix + ("    " if is_last_item else "│   ")
                lines.extend(tree_to_text(value, child_prefix, is_last_item))

        return lines

    # Fetch both README and file structure
    readme_content = fetch_readme()
    tree = build_tree()

