	original_words = len(dialogue.split())
	target_min_words = max(1, int(original_words * 0.1))
	target_max_words = max(1, int(original_words * 0.2))

	# Build Markdown content
	markdown_lines = []
	markdown_lines.append('# Meeting Minutes\n')

	# Add structured sections
	if 'content_type' in analysis_data:
		markdown_lines.append(f'**Content Type:** {analysis_data["content_type"]}\n')
	if 'summary_structure' in analysis_data:
		markdown_lines.append(f'**Summary Structure:** {analysis_data["summary_structure"]}\n')

	markdown_lines.append('## Core Themes')
	if 'core_themes' in analysis_data and analysis_data['core_themes']:
		for theme in analysis_data['core_themes']:
			markdown_lines.append(f'- {theme}')
	else:
		markdown_lines.append('*No core themes identified*')

	markdown_lines.append('\n## Key Information')
	if 'key_information' in analysis_data and analysis_data['key_information']:
		for info in analysis_data['key_information']:
			markdown_lines.append(f'- {info}')
	else:
		markdown_lines.append('*No key information identified*')

	markdown_lines.append('\n## Main Plots')
	if 'main_plots' in analysis_data and analysis_data['main_plots']:
		for plot in analysis_data['main_plots']:
			markdown_lines.append(f'- {plot}')
	else:
		markdown_lines.append('*No main plots identified*')

	markdown_lines.append('\n## Key Figures')
	if 'key_figures' in analysis_data and analysis_data['key_figures']:
		for figure in analysis_data['key_figures']:
			markdown_lines.append(f'- {figure}')
	else:
		markdown_lines.append('*No key figures identified*')

	markdown_lines.append('\n## Important Events')
	if 'important_events' in analysis_data and analysis_data['important_events']:
		for event in analysis_data['important_events']:
			markdown_lines.append(f'- {event}')
	else:
		markdown_lines.append('*No important events identified*')

	markdown_lines.append('\n## Core Viewpoints')
	if 'core_viewpoints' in analysis_data and analysis_data['core_viewpoints']:
		for viewpoint in analysis_data['core_viewpoints']:
			markdown_lines.append(f'- {viewpoint}')
	else:
		markdown_lines.append('*No core viewpoints identified*')

	markdown_lines.append('\n## Organized Summary')
	if 'organized_summary' in analysis_data:
		if isinstance(analysis_data['organized_summary'], list):
			for item in analysis_data['organized_summary']:
				markdown_lines.append(f'{item}')
		else:
			markdown_lines.append(analysis_data['organized_summary'])
	else:
		markdown_lines.append('*No organized summary provided*')

	# Combine all lines
	markdown_content = '\n'.join(markdown_lines)

	# Ensure length is within target range
	current_words = len(markdown_content.split())
	if current_words > target_max_words:
		# Truncate if too long
		words = markdown_content.split()
		markdown_content = ' '.join(words[:target_max_words]) + '...'
	elif current_words < target_min_words and 'organized_summary' in analysis_data:
